// routing.dead-letter: Where a message goes when it dies in a queue, and the loops of that queue
// Generated by `pnpm nx g @app/generators:action routing.dead-letter`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  DeadLetterPathSchema,
  DeadLetterReasonSchema,
  DlxLoopSchema,
  DlxTruncationSchema,
  HEADERS_MAX,
  ROUTING_LIST_MAX,
  RoutingNoteSchema,
  ROUTING_NOTES_MAX,
} from './routing-types.ts';
import {
  SnapshotMetaSchema,
  TOPOLOGY_NAME_MAX,
  TopologyGapsSchema,
  TopologyNameSchema,
  VhostNameSchema,
} from './topology-types.ts';

/** Dead-letter paths one answer lists, at most (the walk keeps this many per start queue). */
export const DEAD_LETTER_PATHS_MAX = 64;
/** Dead-letter loops one answer lists, at most. */
export const DEAD_LETTER_LOOPS_MAX = 16;

export const RoutingDeadLetterInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  vhost: VhostNameSchema,
  /** The queue where the message dies. */
  queue: TopologyNameSchema,
  /** One reason; without it, one path per reason the queue can dead-letter for. */
  reason: DeadLetterReasonSchema.optional(),
  /** The routing keys of the message when known (publish key, CC and BCC); without them the walk is a may-reach. */
  keys: z.array(z.string().max(TOPOLOGY_NAME_MAX)).max(HEADERS_MAX).optional(),
  /** Read the broker again instead of using a snapshot taken in the last seconds. */
  refresh: z.boolean().optional(),
});

export const RoutingDeadLetterOutputSchema = z.strictObject({
  vhost: VhostNameSchema,
  queue: TopologyNameSchema,
  paths: z.array(DeadLetterPathSchema).max(DEAD_LETTER_PATHS_MAX),
  /** Queues that can receive a dead letter on some chain, sorted; the first ROUTING_LIST_MAX. */
  reached: z.array(z.string().max(TOPOLOGY_NAME_MAX)).max(ROUTING_LIST_MAX),
  /** Reached queues that are not listed. */
  reachedMore: z.number().int().nonnegative(),
  /** False when a step is a may-reach, an exchange is unknown, a limit cut the walk, or `gaps` is not empty. */
  exact: z.boolean(),
  notes: z.array(RoutingNoteSchema).max(ROUTING_NOTES_MAX),
  truncation: DlxTruncationSchema,
  /** The dead-letter loops of the vhost that include the queue. */
  loops: z.array(DlxLoopSchema).max(DEAD_LETTER_LOOPS_MAX),
  loopsTruncation: DlxTruncationSchema,
  /**
   * Whether the consumers, which decide whether a ring can reject and so be a retry ring rather than
   * a drop loop, were read whole.
   */
  consumers: z.enum(['read', 'unreadable', 'truncated']),
  gaps: TopologyGapsSchema,
  snapshot: SnapshotMetaSchema,
});

export const routingDeadLetter = defineAction({
  id: 'routing.dead-letter',
  kind: 'query',
  summary:
    'Where a message goes when it dies in a queue, and the dead-letter loops of that queue',
  input: RoutingDeadLetterInputSchema,
  output: RoutingDeadLetterOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({
    connectionId: input.cid,
    vhost: input.vhost,
    kind: 'queue',
    name: input.queue,
  }),
  http: {
    method: 'POST',
    path: '/connections/{cid}/routing/dead-letter-paths',
  },
  mcp: {
    expose: true,
    mutating: false,
    title: 'Dead-letter path of a queue',
    description:
      'Where a message goes when it is rejected, expires, is dropped by a length limit or exceeds the delivery limit in this queue, through the dead-letter exchanges, and the dead-letter loops that include the queue. Nothing is published.',
  },
  cli: { command: 'routing dead-letter' },
  since: '1.0',
});
